// Gerak Cerita: Hentakan membuka map (t = 0.8s - 1.3s), lalu tahan (freeze)
const progBuka = t < 0.8 ? 0 : (t < 1.3 ? mulus((t - 0.8) / 0.5) : 1);
const sudut = progBuka * Math.PI;
const scaleX = Math.cos(sudut);

// Sampul map: kompresi pseudo-3D horizontal & drop-shadow dinamis
const sampul = el('sampulBukaMap');
if (sampul) {
  sampul.setAttribute('transform', `translate(${spineX}, ${spineY}) scale(${scaleX.toFixed(4)}, 1) translate(-${spineX}, -${spineY})`);
  const sElevasi = Math.sin(sudut);
  sampul.style.filter = `drop-shadow(${(-20 * sElevasi).toFixed(1)}px ${(10 + 12 * sElevasi).toFixed(1)}px ${(4 + 16 * sElevasi).toFixed(1)}px rgba(0,0,0,${(0.25 + 0.3 * sElevasi).toFixed(2)}))`;
}

const engsel = el('engselKompresiMap');
if (engsel) engsel.setAttribute('transform', `translate(${spineX}, ${spineY}) scale(${(0.8 + 0.2 * Math.abs(scaleX)).toFixed(3)}, 1) translate(-${spineX}, -${spineY})`);

// Sembunyikan lambang garuda saat membalik (scaleX < 0) & ganti sisi dalam
const garuda = el('garudaEmasMap');
if (garuda) garuda.setAttribute('opacity', scaleX >= 0 ? '1' : '0');

const sisiDalam = el('sisiDalamSampul');
if (sisiDalam) sisiDalam.setAttribute('opacity', scaleX < 0 ? '1' : '0');

// Munculkan lembar dokumen APBN bertahap
const dokumen = el('lembarDokumenAPBN');
if (dokumen) dokumen.setAttribute('opacity', progBuka.toFixed(3));

// Teks angka defisit: muncul bertahap, lalu berdenyut saat narasi menyebut angka
const teksDefisit = el('teksAngkaDefisit');
if (teksDefisit) {
  const munculTeks = t < 1.1 ? 0 : mulus(Math.min(1, (t - 1.1) / 0.4));
  teksDefisit.setAttribute('opacity', munculTeks.toFixed(3));
  if (t >= 2.4 && t <= 4.0) {
    const denyutAngka = (1 + 0.05 * Math.sin((t - 2.4) * 8)).toFixed(3);
    teksDefisit.setAttribute('transform', `translate(960, 740) scale(${denyutAngka}) translate(-960, -740)`);
  }
}

// Sinkronkan lengan kanan mengikuti busur sampul (0.8s - 1.3s), lalu freeze
const lenganKanan = el('lenganKanan');
if (lenganKanan) {
  const rotLengan = -progBuka * 34;
  lenganKanan.setAttribute('transform', `rotate(${rotLengan.toFixed(2)} ${bahuX} ${bahuY})`);
}

