  const b = roda.getBBox ? roda.getBBox() : null;
  const cx = b ? b.x + b.width / 2 : 0;
  const cy = b ? b.y + b.height / 2 : 0;
  let rot = 0;
  if (t < 2.1) {
    rot = (t * 1500) % 360;
