const tCetek = 0.8;
const api = el('apiBiruKompor');
const lidahApi = el('lidahApiStabil');

if (t < tCetek) {
  if (api) api.setAttribute('opacity', '0');
  if (lidahApi) lidahApi.setAttribute('opacity', '0');
} else {
  const dtCetek = t - tCetek;
  const sentakCetek = dtCetek < 0.2 ? 1.0 + (1 - dtCetek / 0.2) * 0.6 : 1.0;
  const mikroFlicker = Math.sin(t * 34) * 0.05 + Math.cos(t * 20) * 0.03;
  const flickerY = (Math.sin(t * 28) * 0.7).toFixed(2);

  if (api) {
    const opApi = Math.min(1, Math.max(0, 0.9 * sentakCetek + mikroFlicker));
    api.setAttribute('opacity', opApi.toFixed(2));
    api.setAttribute('transform', `translate(0, ${flickerY})`);
  }
  if (lidahApi) {
    const opLidah = Math.min(1, Math.max(0, 0.8 * sentakCetek + mikroFlicker * 1.4));
    lidahApi.setAttribute('opacity', opLidah.toFixed(2));
    lidahApi.setAttribute('transform', `translate(0, ${(flickerY * 1.3).toFixed(2)})`);
  }
}

