if (t < tMulaiRem) {
  sudutRoda = t * w0;
} else if (t < tMacetTotal) {
  const u = (t - tMulaiRem) / dtPengereman;
  const inersiaPengereman = u - u * u + (u * u * u) / 3;
  sudutRoda = tMulaiRem * w0 + w0 * dtPengereman * inersiaPengereman;
} else {
  const sudutBerhenti = tMulaiRem * w0 + w0 * dtPengereman * (1 / 3);
  const tPasca = t - tMacetTotal;
  const lentingMikro = tPasca < 0.35 ? Math.sin(tPasca * 30) * Math.exp(-tPasca * 12) * -1.5 : 0;
  sudutRoda = sudutBerhenti + lentingMikro;
}

if (roda) {
  roda.setAttribute('transform', `rotate(${sudutRoda.toFixed(2)} 960 540)`);
}

const jepit = mulus(Math.max(0, Math.min(1, (t - 1.85) / 0.55)));
const geserJepit = jepit * 24;

let getarHentakan = 0;
if (t >= 2.05 && t < tMacetTotal) {
  const intensitas = (t - 2.05) / (tMacetTotal - 2.05);
  getarHentakan = Math.sin(t * 75) * (2.8 * intensitas);
} else if (t >= tMacetTotal && t < 3.8) {
  const tSentak = t - tMacetTotal;
  getarHentakan = Math.sin(tSentak * 34) * Math.exp(-tSentak * 5.2) * 5.5;
}

if (rahang) {
  rahang.setAttribute('transform', `translate(${(geserJepit + getarHentakan).toFixed(2)}, ${(getarHentakan * 0.35).toFixed(2)})`);
}
if (silinder) {
  silinder.setAttribute('transform', `translate(${(geserJepit * 0.4 + getarHentakan * 0.45).toFixed(2)}, 0)`);
}
if (pasak) {
  pasak.setAttribute('transform', `translate(${geserJepit.toFixed(2)}, 0)`);
}

if (percikan) {
  if (t >= 2.1 && t < 3.1) {
    const pPercik = (t - 2.1) / 1.0;
    const nyala = Math.sin(t * 90) > -0.25 ? (1 - pPercik * 0.85) : 0.15;
    percikan.setAttribute('opacity', nyala.toFixed(2));
    percikan.setAttribute('transform', `scale(${(1 + Math.sin(t * 40) * 0.25).toFixed(2)})`);
  } else {
    percikan.setAttribute('opacity', '0');
  }
}

