    const opacAsap = t < 3.1 ? mulus(tAsap / 0.85) : Math.max(0, 1 - (t - 3.1) / 3.4);
    const naikY = -tAsap * 16;
    const mengembang = 1 + tAsap * 0.18;
    asap.setAttribute('opacity', (opacAsap * 0.85).toFixed(2));
    asap.setAttribute('transform', `translate(0, ${naikY.toFixed(1)}) scale(${mengembang.toFixed(2)})`);
  } else {
    asap.setAttribute('opacity', '0');
  }
}

